#version 300 es
precision highp float;

uniform vec3 iResolution;
uniform float iTime;

float hash12(vec2 p) {
    vec3 p3  = fract(p.xyx * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float noise(vec3 x) {
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    float n = p.x + p.y * 157.0 + p.z * 113.0;
    float res = mix(mix(mix(hash12(vec2(n, 0.0)), hash12(vec2(n + 1.0, 0.0)), f.x),
                        mix(hash12(vec2(n, 157.0)), hash12(vec2(n + 1.0, 157.0)), f.x), f.y),
                    mix(mix(hash12(vec2(n + 113.0, 0.0)), hash12(vec2(n + 1.0 + 113.0, 0.0)), f.x),
                        mix(hash12(vec2(n + 113.0, 157.0)), hash12(vec2(n + 1.0 + 113.0, 157.0)), f.x), f.y), f.z);
    return res;
}

float fbm(vec3 p) {
    float f = 0.0;
    f += 0.5000 * noise(p);
    f += 0.2500 * noise(p * 2.0);
    f += 0.1250 * noise(p * 4.0);
    f += 0.0625 * noise(p * 8.0);
    return f / 0.9375;
}

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

mat3 viewMatrix(vec3 eye, vec3 center, vec3 up) {
    vec3 f = normalize(center - eye);
    vec3 s = normalize(cross(f, up));
    vec3 u = cross(s, f);
    return mat3(s, u, -f);
}

vec3 getRayDir(vec2 uv, vec3 eye, vec3 center, vec3 up) {
    mat3 vm = viewMatrix(eye, center, up);
    vec3 dir = vm * normalize(vec3(uv, 2.0));
    return dir;
}

float mapClouds(vec3 p) {
    float density = fbm(p * 0.05 + iTime * 0.005) * 0.8 + 0.2;
    density -= fbm(p * 0.1 + iTime * 0.01) * 0.4;
    density = clamp(density, 0.0, 1.0);
    return density;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float camTime = iTime * 0.1;
    vec3 camPos = vec3(sin(camTime * 0.5) * 60.0, 30.0 + sin(camTime * 0.3) * 10.0, cos(camTime * 0.5) * 60.0);
    vec3 camTarget = vec3(0.0, 20.0, 0.0);
    vec3 camUp = vec3(0.0, 1.0, 0.0);

    vec3 rayDir = getRayDir(uv, camPos, camTarget, camUp);
    vec3 rayOrigin = camPos;

    vec3 sunDir = normalize(vec3(0.5, 0.5, -0.5));
    vec3 skyColor = vec3(0.5, 0.7, 1.0);
    vec3 sunColor = vec3(1.0, 0.9, 0.7);
    float sunIntensity = 100.0;

    float totalDensity = 0.0;
    vec3 finalColor = vec3(0.0);
    vec3 currentPos = rayOrigin;

    float stepSize = 1.0;
    float maxDist = 200.0;

    for (int i = 0; i < 64; ++i) {
        if (length(currentPos - rayOrigin) > maxDist) break;

        float density = mapClouds(currentPos);

        if (density > 0.01) {
            float lightAccum = 0.0;
            vec3 lightSamplePos = currentPos;
            for (int j = 0; j < 8; ++j) {
                lightSamplePos += sunDir * stepSize * 2.0;
                lightAccum += mapClouds(lightSamplePos);
            }
            lightAccum = exp(-lightAccum * 2.0);

            vec3 color = mix(vec3(0.8, 0.8, 0.8), vec3(1.0, 1.0, 1.0), density);
            vec3 litColor = color * lightAccum + sunColor * pow(max(0.0, dot(rayDir, sunDir)), 10.0) * sunIntensity * density;

            float alpha = 1.0 - exp(-density * stepSize * 0.5);
            finalColor = mix(finalColor, litColor, alpha);
            totalDensity += alpha;
        }

        currentPos += rayDir * stepSize;
    }

    finalColor = mix(skyColor, finalColor, clamp(totalDensity, 0.0, 1.0));

    float sunDot = max(0.0, dot(rayDir, sunDir));
    finalColor += sunColor * pow(sunDot, 20.0) * 0.5;
    finalColor += sunColor * pow(sunDot, 200.0) * 1.5; 

    fragColor = vec4(finalColor, 1.0);
}

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec2 permute(vec2 p) {
    return mod((p * 34.0 + 1.0) * p, 289.0);
}

float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439); // (3.0-sqrt(3.0))/6.0, (sqrt(3.0)-1.0)/2.0
    vec2 i = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 xmmx = vec4(x0.xy, x0.xy - i1);
    vec4 s = max(0.0, 0.5 - floor(xmmx * xmmx));
    vec4 h = vec4(xmmx.x, xmmx.y, xmmx.z, xmmx.w) * s;
    return dot(h, vec4(72.48419614457788, 72.48419614457788, 72.48419614457788, 72.48419614457788));
}

float fbm(vec2 st) {
    float value = 0.0;
    float amplitude = 0.5;
    for (int i = 0; i < 5; i++) {
        value += amplitude * snoise(st);
        st *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 cell = uv * 3.0;
    cell.x += iTime * 0.1;
    float noiseVal = fbm(cell);
    float cloudCoverage = 0.6 + 0.4 * snoise(vec2(uv.x * 5.0, iTime * 0.05));
    float alpha = smoothstep(cloudCoverage * 0.5, cloudCoverage * 0.7, noiseVal);
    vec3 skyColor = mix(vec3(0.53, 0.81, 0.98), vec3(0.12, 0.56, 1.0), uv.y * 0.8 + 0.2);
    vec3 cloudColor = vec3(0.95);
    fragColor = vec4(mix(skyColor, cloudColor, alpha), 1.0);
}

#define MAX_STEPS 100
#define MAX_DIST 100.0
#define SURF_DIST 0.001

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float opUnion(float d1, float d2) {
    return min(d1, d2);
}

float map(vec3 p) {
    float sphere1 = sdSphere(p - vec3(sin(iTime * 1.5) * 2.0, cos(iTime * 0.8) * 2.0, 0.0), 1.0);
    float sphere2 = sdSphere(p - vec3(cos(iTime * 1.0) * 2.0, sin(iTime * 1.2) * 2.0, 0.0), 1.0);
    float box = sdBox(p - vec3(0.0, 0.0, -3.0), vec3(5.0, 5.0, 0.5));
    return opUnion(opUnion(sphere1, sphere2), box);
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

float rayMarch(vec3 ro, vec3 rd, float startDist) {
    float dO = startDist;
    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        float dS = map(p);
        dO += dS;
        if (dS < SURF_DIST || dO > MAX_DIST) break;
    }
    return dO;
}

// Basic hash function for random numbers
float hash12(vec2 p) {
    vec3 p3  = fract(p.xyx * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Basic noise function
float noise(vec3 x) {
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);
    float n = p.x + p.y*157.0 + 113.0*p.z;
    return mix(mix(mix(hash12(n+0.0), hash12(n+1.0), f.x),
                   mix(hash12(n+157.0), hash12(n+158.0), f.x), f.y),
               mix(mix(hash12(n+113.0), hash12(n+114.0), f.x),
                   mix(hash12(n+270.0), hash12(n+271.0), f.x), f.y), f.z);
}

const float ROUGHNESS = 0.5;

// Fresnel approximation
float fresnel(float cosAngle, float reflectivity) {
    return reflectivity + (1.0 - reflectivity) * pow(1.0 - cosAngle, 5.0);
}

// Schlick's approximation for Fresnel
vec3 schlickFresnel(float R0, float cosTheta) {
    return vec3(R0 + (1.0 - R0) * pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0));
}

// GGX Normal Distribution Function
float D_GGX(float NdotH, float roughness) {
    float a = roughness * roughness;
    float a2 = a * a;
    float NdotH2 = NdotH * NdotH;
    float nom = a2;
    float denom = (NdotH2 * (a2 - 1.0) + 1.0);
    denom = 3.1415926535 * denom * denom;
    return nom / denom;
}

// Geometric Shadowing (Smith's method for GGX)
float G_Smith(float NdotV, float NdotL, float roughness) {
    float a = roughness * roughness;
    float k = (a + 1.0);
    float G_V = (NdotV) / (NdotV * (1.0 - k) + k);
    float G_L = (NdotL) / (NdotL * (1.0 - k) + k);
    return G_V * G_L;
}

vec3 calculateBlinnPhong(vec3 L, vec3 V, vec3 N, vec3 lightColor, vec3 albedo, float shininess) {
    vec3 H = normalize(L + V);
    float NdotL = max(0.0, dot(N, L));
    float NdotH = max(0.0, dot(N, H));

    // Diffuse
    vec3 diffuse = albedo * NdotL;

    // Specular
    float spec = pow(NdotH, shininess);
    vec3 specular = lightColor * spec;

    return (diffuse + specular);
}

vec3 getColor(vec3 ro, vec3 rd) {
    vec3 col = vec3(0.0);

    // Light source
    vec3 lightPos = vec3(5.0 * sin(iTime), 5.0, 5.0 * cos(iTime));
    vec3 lightColor = vec3(1.0, 0.9, 0.8);

    float d = rayMarch(ro, rd, 0.0);

    if (d < MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 N = getNormal(p);

        // Refraction/Reflection (Simple Glass)
        float refractiveIndex = 1.5; // Glass
        float R0 = pow((1.0 - refractiveIndex) / (1.0 + refractiveIndex), 2.0);
        float cosTheta = dot(rd, N);
        vec3 F = schlickFresnel(R0, cosTheta);

        // Reflection ray
        vec3 reflectedRayDir = reflect(rd, N);
        float reflectedDist = rayMarch(p + N * SURF_DIST * 2.0, reflectedRayDir, 0.0);
        vec3 reflectedColor = vec3(0.0);
        if (reflectedDist < MAX_DIST) {
            vec3 reflectedP = p + N * SURF_DIST * 2.0 + reflectedRayDir * reflectedDist;
            reflectedColor = vec3(0.8, 0.9, 1.0) * (1.0 - (reflectedDist / MAX_DIST)); // Simple environment map style

            // Secondary reflection
            vec3 secRefN = getNormal(reflectedP);
            vec3 secReflectedRayDir = reflect(reflectedRayDir, secRefN);
            float secReflectedDist = rayMarch(reflectedP + secRefN * SURF_DIST * 2.0, secReflectedRayDir, 0.0);
            if (secReflectedDist < MAX_DIST) {
                reflectedColor += vec3(0.2);
            }
        }

        // Refraction ray
        vec3 refractedRayDir = refract(rd, N, 1.0 / refractiveIndex); // Air to glass
        vec3 refractedColor = vec3(0.0);
        if (dot(refractedRayDir, refractedRayDir) > 0.0) { // Check for total internal reflection
            float refractedDist = rayMarch(p - N * SURF_DIST * 2.0, refractedRayDir, 0.0);
            if (refractedDist < MAX_DIST) {
                vec3 refractedP = p - N * SURF_DIST * 2.0 + refractedRayDir * refractedDist;

                // Re-refract out of glass into air
                vec3 N_inner = -getNormal(refractedP);
                vec3 refractedRayDir_out = refract(refractedRayDir, N_inner, refractiveIndex); // Glass to air
                if (dot(refractedRayDir_out, refractedRayDir_out) > 0.0) {
                     float refractedDist_out = rayMarch(refractedP + N_inner * SURF_DIST * 2.0, refractedRayDir_out, 0.0);
                     if (refractedDist_out < MAX_DIST) {
                         vec3 finalRefractedP = refractedP + N_inner * SURF_DIST * 2.0 + refractedRayDir_out * refractedDist_out;
                         refractedColor = vec3(0.5, 0.8, 1.0) * (1.0 - (refractedDist_out / MAX_DIST));
                         // Diffraction effect - tint based on angle or distance
                         refractedColor += 0.2 * vec3(1.0, 0.8, 0.5) * (1.0 - abs(dot(refractedRayDir_out, rd)));
                     }
                }
            }
        }

        // Combine reflection and refraction with Fresnel
        col = mix(refractedColor, reflectedColor, F);

        // Simple ambient occlusion
        float ao = 1.0 - N.y * 0.2 - N.x * 0.1; // Simple hack, could be better
        col *= ao;

        // Add some basic light from the scene
        vec3 L = normalize(lightPos - p);
        float NdotL = max(0.0, dot(N, L));

        // Simple shadowing
        float shadowRay = rayMarch(p + N * SURF_DIST * 3.0, L, 0.0);
        float shadow = 1.0;
        if (shadowRay < length(lightPos - p)) {
            shadow = 0.5;
        }

        col += calculateBlinnPhong(L, -rd, N, lightColor, vec3(0.1), 32.0) * NdotL * shadow;

        // Add subtle diffraction colors directly based on normal/view dot product for edges
        float rimLight = pow(1.0 - max(0.0, dot(N, -rd)), 3.0);
        col += rimLight * vec3(0.8, 0.4, 0.1) * 0.5;

    } else {
        // Background color (simple sky)
        col = mix(vec3(0.6, 0.7, 0.9), vec3(0.9, 0.8, 0.7), pow(max(0.0, rd.y), 0.5));
        // Stars
        float starVal = noise(rd * 1000.0 + iTime * 10.0);
        if (starVal > 0.95) {
            col += vec3(starVal); // Simple stars
        }
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 0.0, 5.0); // Camera position
    vec3 target = vec3(0.0, 0.0, 0.0);
    float zoom = 1.5; // Adjust zoom

    // Camera rotation
    mat3 camRot;
    float angleX = iMouse.y * 0.005;
    float angleY = iMouse.x * 0.005;

    // Rotate about Y axis
     mat3 rotY = mat3(
        cos(angleY), 0.0, sin(angleY),
        0.0, 1.0, 0.0,
        -sin(angleY), 0.0, cos(angleY)
     );

     // Rotate about X axis
     mat3 rotX = mat3(
        1.0, 0.0, 0.0,
        0.0, cos(angleX), -sin(angleX),
        0.0, sin(angleX), cos(angleX)
     );

    camRot = rotY * rotX; // Apply rotations

    vec3 forward = normalize(target - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = normalize(cross(forward, right));

    vec3 rd = normalize(uv.x * right * zoom + uv.y * up * zoom + forward);
    rd = camRot * rd; // Apply camera rotation to ray direction

    vec3 col = getColor(ro + camRot * (-target), rd);

    fragColor = vec4(col, 1.0);
}

