        mul *= 0.5;
    }
    return f;
}

mat2 rotate2d(float angle) {
    return mat2(cos(angle), -sin(angle),
                sin(angle), cos(angle));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;

    vec3 camPos = vec3(0.0, 3.0 + iTime * 0.5, iTime * 2.0);
    vec3 camTar = camPos + vec3(0.0, -0.1, 1.0);
    vec3 camUp = vec3(0.0, 1.0, 0.0);

    vec3 forward = normalize(camTar - camPos);
    vec3 right = normalize(cross(forward, camUp));
    vec3 actualUp = normalize(cross(right, forward));

    vec3 rayDir = normalize(forward + right * uv.x * 1.5 + actualUp * uv.y * 1.0);

    float totalDist = 0.0;
    vec3 p = camPos;

    for (int i = 0; i < 60; i++) {
        float h = (fbm(p.xz * 0.05 + vec2(0.0, iTime * 0.1)) * 10.0 + 
                   fbm(p.xz * 0.2 + vec2(0.0, iTime * 0.2)) * 3.0) - p.y;

        float dist = max(0.01, h * 0.5);

        if (h < 0.01) break;

        p += rayDir * dist;
        totalDist += dist;

        if (totalDist > 100.0) {
            break;
        }
    }

    float height = (fbm(p.xz * 0.05 + vec2(0.0, iTime * 0.1)) * 10.0 + 
                    fbm(p.xz * 0.2 + vec2(0.0, iTime * 0.2)) * 3.0);

    vec3 normal = normalize(vec3(
        (fbm(p.xz * 0.05 + vec2(0.1, iTime * 0.1)) * 10.0 + fbm(p.xz * 0.2 + vec2(0.1, iTime * 0.2)) * 3.0) - height,
        1.0,
        (fbm(p.xz * 0.05 + vec2(0.0, iTime * 0.1 + 0.1)) * 10.0 + fbm(p.xz * 0.2 + vec2(0.0, iTime * 0.2 + 0.1)) * 3.0) - height
    ));

    vec3 lightDir = normalize(vec3(0.5, 0.8, -0.5));
    float diff = max(0.0, dot(normal, lightDir));

    vec3 ambientColor = vec3(0.2, 0.3, 0.4);
    vec3 desertColor = mix(vec3(0.8, 0.6, 0.3), vec3(0.6, 0.4, 0.2), clamp(height / 15.0, 0.0, 1.0));
    desertColor += fbm(p.xz * 3.0) * 0.05;

    vec3 finalColor = ambientColor + desertColor * diff;

    vec3 fogColor = vec3(0.6, 0.7, 0.9);
    float fogFactor = clamp(totalDist / 80.0, 0.0, 1.0);
    finalColor = mix(finalColor, fogColor, fogFactor);

    // Sky
    if (totalDist > 99.0) {
        vec3 skyColor = mix(vec3(0.4, 0.6, 0.8), vec3(0.8, 0.9, 1.0), 1.0 - min(1.0, rayDir.y));
        finalColor = mix(finalColor, skyColor, 1.0);
    }

    fragColor = vec4(finalColor, 1.0);
}

float hash12(vec2 p)
{
    vec3 p3  = fract(p.xyx * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p)
{
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));

    vec2 u = f*f*(3.0-2.0*f);
    return mix(a, b, u.x) + (c - a)*u.y*(1.0 - u.x) + (d - b)*u.x*u.y;
}

float fbm(vec2 p)
{
    float G = 0.5;
    float H = 0.5;
    float lacunarity = 2.0;
    float octaves = 4.0;
    float value = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;
    for (int i = 0; i < int(octaves); i++) {
        value += amplitude * noise(p * frequency);
        frequency *= lacunarity;
        amplitude *= G;
    }
    return value;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec2 R = iResolution.xy;

    float camZoom = 3.0;
    float camTime = iTime * 0.1;

    vec3 ro = vec3(camTime*2.0, 1.5, camTime);
    vec3 rd = normalize(vec3((fragCoord - 0.5 * R) / R.y * camZoom, 1.0));

    float t = 0.0;
    float dist = 0.0;
    vec3 p = ro;

    vec3 finalColor = vec3(0.0);

    for (int i = 0; i < 50; ++i)
    {
        p = ro + rd * t;

        float elevation = mix(0.2, 0.5, fbm(p.xz * 1.5 + camTime * 0.2));
        elevation = max(0.0, elevation - p.y);

        float oceanDepth = p.y;

        if (elevation > 0.001) // Hill hit
        {
            vec3 hillColor = mix(vec3(0.2, 0.5, 0.1), vec3(0.3, 0.6, 0.2), clamp(elevation * 2.0, 0.0, 1.0));
            hillColor = mix(hillColor, vec3(0.4, 0.45, 0.3), pow(clamp(dot(rd, vec3(0.0, 1.0, 0.0)) * 0.5 + 0.5, 0.0, 1.0), 3.0));
            finalColor = hillColor;
            break;
        }
        else if (oceanDepth < 0.0) // Ocean hit
        {
            float depthFactor = clamp(abs(oceanDepth) * 0.2, 0.0, 1.0);
            vec3 oceanColor = mix(vec3(0.1, 0.3, 0.5), vec3(0.0, 0.1, 0.3), depthFactor);

            vec2 wavePos = p.xz * 0.5 + camTime * 0.5;
            float wave = sin(wavePos.x * 10.0 + iTime * 5.0) * sin(wavePos.y * 12.0 + iTime * 4.0) * 0.02;
            oceanColor += wave * 0.1;

            finalColor = oceanColor;
            break;
        }

        t += 0.1;

        if (t > 100.0) // Max distance
        {
            break;
        }
    }

    // Sky
    vec3 sunDir = normalize(vec3(0.0, 0.5, -0.8));
    float sun = max(0.0, dot(rd, sunDir));
    vec3 skyColor = mix(vec3(0.2, 0.3, 0.6), vec3(0.8, 0.9, 1.0), pow(1.0 - uv.y, 4.0));
    skyColor += sun * 1.5 * vec3(1.0, 0.8, 0.6);

    // Horizon
    float horizon = 1.0 - pow(uv.y, 0.5);
    skyColor = mix(skyColor, finalColor.rgb, clamp(horizon * 2.0, 0.0, 1.0));

    finalColor = mix(skyColor, finalColor, step(0.0, t)); // Blend with sky if nothing hit

    fragColor = vec4(finalColor, 1.0);
}

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec2 permute(vec2 p) {
    return mod((p * 34.0 + 1.0) * p, 289.0);
}

float snoise(vec2 v) {
    vec2 i = floor(v);
    vec2 f = fract(v);

    vec2 u = f * f * (3.0 - 2.0 * f);

    vec2 a = permute(i + vec2(0.0, 0.0));
    vec2 b = permute(i + vec2(1.0, 0.0));
    vec2 c = permute(i + vec2(0.0, 1.0));
    vec2 d = permute(i + vec2(1.0, 1.0));

    float res = mix(mix(random(a), random(b), u.x), mix(random(c), random(d), u.x), u.y);
    return res;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;

    vec2 p = uv * 8.0;
    float t = iTime * 0.1;

    p += vec2(snoise(p * 0.5 + t), snoise(p * 0.6 - t)) * 1.5;

    float n = snoise(p);
    n += snoise(p * 2.0) * 0.5;
    n += snoise(p * 4.0) * 0.25;
    n = pow(clamp(n * 1.2, 0.0, 1.0), 1.5);

    vec3 color = mix(vec3(0.1, 0.3, 0.5), vec3(0.9, 0.6, 0.2), n);
    color = mix(color, vec3(0.8, 0.1, 0.1), smoothstep(0.8, 1.0, n));

    fragColor = vec4(color, 1.0);
}

float hash12(vec2 p) {
    vec3 p3  = fract(p.xyx * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
    vec3 p3 = fract(p.xyx * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xy+p3.yz)*p3.zx);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f*f*(3.0-2.0*f);
    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        f += amp * noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

vec3 raymarchOcean(vec3 ro, vec3 rd, float tMax) {
    float totalDist = 0.0;
    int steps = 60;
    float hModifier = pow(hash12(gl_FragCoord.xy) * 0.8 + 0.2, 2.0);
    hModifier = mix(0.1, 0.9, hModifier);

    for (int i = 0; i < steps; i++) {
        vec3 p = ro + rd * totalDist;
        float height = fbm(p.xz * 0.1 - iTime * 0.05) * 2.0 + fbm(p.xz * 0.3 - iTime * 0.1) * 0.5 + fbm(p.xz * 0.5 + iTime * 0.03) * 0.2;
        height += fbm(p.xz * 0.05) * 5.0;
        height *= hModifier;
        float distToOcean = p.y - height;

        if (distToOcean < 0.01) {
            vec2 eps = vec2(0.01, 0.0);
            vec3 n;
            float hX1 = fbm((p.xz + eps.xy) * 0.1 - iTime * 0.05) * 2.0 + fbm((p.xz + eps.xy) * 0.3 - iTime * 0.1) * 0.5 + fbm((p.xz + eps.xy) * 0.5 + iTime * 0.03) * 0.2 + fbm((p.xz + eps.xy) * 0.05) * 5.0;
            float hX2 = fbm((p.xz - eps.xy) * 0.1 - iTime * 0.05) * 2.0 + fbm((p.xz - eps.xy) * 0.3 - iTime * 0.1) * 0.5 + fbm((p.xz - eps.xy) * 0.5 + iTime * 0.03) * 0.2 + fbm((p.xz - eps.xy) * 0.05) * 5.0;
            float hZ1 = fbm((p.xz + eps.yx) * 0.1 - iTime * 0.05) * 2.0 + fbm((p.xz + eps.yx) * 0.3 - iTime * 0.1) * 0.5 + fbm((p.xz + eps.yx) * 0.5 + iTime * 0.03) * 0.2 + fbm((p.xz + eps.yx) * 0.05) * 5.0;
            float hZ2 = fbm((p.xz - eps.yx) * 0.1 - iTime * 0.05) * 2.0 + fbm((p.xz - eps.yx) * 0.3 - iTime * 0.1) * 0.5 + fbm((p.xz - eps.yx) * 0.5 + iTime * 0.03) * 0.2 + fbm((p.xz - eps.yx) * 0.05) * 5.0;
            hX1 *= hModifier; hX2 *= hModifier; hZ1 *= hModifier; hZ2 *= hModifier;

            n.x = hX2 - hX1;
            n.y = 2.0 * eps.x;
            n.z = hZ2 - hZ1;
            n = normalize(n);

            vec3 lightDir = normalize(vec3(0.5, 0.7, 0.8));
            float diffuse = max(0.0, dot(n, lightDir));
            vec3 viewDir = normalize(ro - p);
            vec3 halfVec = normalize(lightDir + viewDir);
            float specular = pow(max(0.0, dot(n, halfVec)), 64.0);

            vec3 oceanColor = mix(vec3(0.0, 0.1, 0.2), vec3(0.1, 0.4, 0.6), diffuse);
            oceanColor += specular * 0.5;
            oceanColor = mix(oceanColor, vec3(0.9, 0.95, 1.0), pow(1.0 - max(0.0, dot(n, viewDir)), 3.0)); // Fresnel
            oceanColor += pow(max(0.0, -dot(n, lightDir)), 8.0) * 0.5; // Backlight / scattering
            return oceanColor;
        }
        totalDist += distToOcean * 0.8;
        if (totalDist > tMax) break;
    }
    return vec3(0.5, 0.7, 1.0) - rd.y * 0.5; // Sky color
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float mouseX = iMouse.x / iResolution.x * 6.28 - 3.14; // Yaw
    float mouseY = iMouse.y / iResolution.y * 3.14 - 1.57; // Pitch
    if (iMouse.z > 0.0) {
        // Mouse control active, update camera angles
    } else {
        // Default camera if mouse not active
        mouseX = sin(iTime * 0.1) * 0.5 + 1.0;
        mouseY = sin(iTime * 0.05) * 0.2 + 0.5;
    }

    vec3 ro = vec3(0.0, 5.0, -10.0); // Camera origin

    mat3 rotX = mat3(
        1.0, 0.0, 0.0,
        0.0, cos(mouseY), -sin(mouseY),
        0.0, sin(mouseY), cos(mouseY)
    );
    mat3 rotY = mat3(
        cos(mouseX), 0.0, sin(mouseX),
        0.0, 1.0, 0.0,
        -sin(mouseX), 0.0, cos(mouseX)
    );

    vec3 rd = rotY * rotX * normalize(vec3(uv.x, uv.y, 1.5)); // Ray direction

    vec3 col = raymarchOcean(ro, rd, 100.0);

    fragColor = vec4(col, 1.0);
}

#define PI 3.14159265359

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    f = f * f * (3.0 - 2.0 * f);
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos(2.0 * PI * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / min(iResolution.x, iResolution.y);
    vec3 finalColor = vec3(0.0);

    // Stars in background
    float starField = noise(uv * iResolution.x / 10.0 + iTime * 0.05);
    if (starField > 0.9) {
        finalColor += vec3(1.0, 0.9, 0.8) * (starField - 0.9) * 10.0;
    }

    // Exoplanet
    vec3 planetPos = vec3(-0.3, 0.0, 0.0);
    float planetRadius = 0.5;
    float distToPlanet = length(uv - planetPos.xy);
    if (distToPlanet < planetRadius) {
        vec2 planetUV = (uv - planetPos.xy) / planetRadius;
        float lifeNoise = noise(planetUV * 10.0 + iTime * 0.1);
        vec3 planetColor = mix(vec3(0.1, 0.4, 0.1), vec3(0.3, 0.6, 0.3), lifeNoise);
        float oceanNoise = noise(planetUV * 5.0 + iTime * 0.05);
        if (oceanNoise < 0.3) {
            planetColor = mix(planetColor, vec3(0.0, 0.2, 0.4), 0.7);
        }
        float light = dot(normalize(vec3(uv - planetPos.xy, sqrt(max(0.0, planetRadius * planetRadius - distToPlanet * distToPlanet)))), normalize(vec3(0.5, 0.5, 1.0)));
        planetColor *= (0.5 + 0.5 * light);
        finalColor = mix(finalColor, planetColor, smoothstep(planetRadius, planetRadius * 0.9, distToPlanet));
    }

    // Moons
    for (int i = 0; i < 2; ++i) {
        float orbitRadius = 0.8 + float(i) * 0.3;
        float orbitSpeed = 0.5 + float(i) * 0.2;
        float moonAngle = iTime * orbitSpeed + float(i) * PI;
        vec2 moonPos = vec2(cos(moonAngle), sin(moonAngle)) * orbitRadius + planetPos.xy;
        float moonRadius = 0.1 + float(i) * 0.03;
        float distToMoon = length(uv - moonPos);

        if (distToMoon < moonRadius) {
            vec2 moonUV = (uv - moonPos) / moonRadius;
            vec3 moonBaseColor = palette(float(i) * 0.5 + 0.2);
            float craterNoise = noise(moonUV * 15.0);
            moonBaseColor = mix(moonBaseColor, vec3(0.2, 0.2, 0.2), craterNoise * 0.7);
            float light = dot(normalize(vec3(uv - moonPos, sqrt(max(0.0, moonRadius * moonRadius - distToMoon * distToMoon)))), normalize(vec3(0.5, 0.5, 1.0)));
            moonBaseColor *= (0.5 + 0.5 * light);
            finalColor = mix(finalColor, moonBaseColor, smoothstep(moonRadius, moonRadius * 0.9, distToMoon));
        }
    }

    fragColor = vec4(finalColor, 1.0);
}

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

vec2 hash(vec2 p) {
    p = fract(p * vec2(5.3983, 5.4427));
    p += dot(p.yx, p.xy + vec2(21.5351, 14.3137));
    return fract(vec2(p.x * p.y, p.x + p.y));
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    vec2 u = f * f * (3.0 - 2.0 * f);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    float mul = 0.5;
    for (int i = 0; i < 5; i++) {
        f += mul * noise(p);
        p *= 2.0;
        mul *= 0.5;
    }
    return f;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 rayDir = normalize(vec3(uv, 1.5));
    vec3 rayOrigin = vec3(0.0, 0.0, -iTime * 0.1);

    float mousePress = float(iMouse.z > 0.0);
    float warpSpeed = 1.0 + mousePress * 5.0;
    float warpEffect = mousePress * 0.5;

    float time = iTime * 0.1 * warpSpeed;

    vec3 finalColor = vec3(0.0);

    vec2 p = rayDir.xy / rayDir.z;
    float starCount = 0.0;
    for (int i = 0; i < 80; i++) {
        vec2 starPos = hash(vec2(float(i) * 0.01, float(i) * 0.01 + 0.1));
        starPos = starPos * 200.0 - 100.0;
        starPos.x += mod(time * 50.0, 200.0);
        starPos.y += mod(time * 30.0, 150.0);
        starPos = fract(starPos / 200.0) * 200.0 - 100.0;

        float starZ = fract(random(starPos.xy) + time / 5.0) * 100.0;
        starZ = mix(starZ, starZ * starZ * 0.1, warpEffect);

        vec2 projectedStar = starPos / starZ;
        vec2 diff = projectedStar - p;

        float dist = length(diff);
        float starSize = mix(0.005, 0.02, random(starPos.xy + 0.5));
        starSize *= (1.0 + warpEffect * 5.0 * random(starPos.xy + 0.8));
        float starBrightness = clamp(mix(1.0, 0.0, texture(BufferA, mod(starPos.xy, 1.0)).r * 0.9 + 0.1) / (dist * 100.0), 0.0, 1.0);
        starBrightness *= smoothstep(0.0, starSize, starSize - dist);
        starBrightness *= (0.5 + 0.5 * sin(starZ * 10.0 + iTime * 2.0));

        vec3 starColor = mix(vec3(0.8, 0.9, 1.0), vec3(1.0, 0.6, 0.4), random(starPos.xy + 0.1));
        finalColor += starColor * starBrightness;
        starCount += starBrightness;
    }

    float nebula = fbm(uv * 2.0 + vec2(time * 0.1, time * 0.05));
    vec3 nebulaColor = vec3(0.1, 0.05, 0.2) + nebula * 0.5 * vec3(0.2, 0.1, 0.3);
    finalColor += nebulaColor * (1.0 - starCount * 0.5);

    finalColor *= (1.0 - warpEffect * 0.5);
    finalColor = mix(finalColor, vec3(0.5, 0.8, 1.0) * (0.8 + 0.2 * sin(iTime * 10.0)), warpEffect * smoothstep(0.0, 0.5, length(uv)));

    fragColor = vec4(finalColor, 1.0);
}

