void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 aspect = vec2(iResolution.x / iResolution.y, 1.0);
    vec2 center = vec2(0.5, 0.5);

    float scale = 0.7;
    float speed = 0.5;

    vec2 noiseUV = uv * 5.0;
    float noise = hash12(floor(noiseUV + vec2(0.0, iTime * 0.1)));
    noise = mix(noise, hash12(floor(noiseUV + vec2(1.0, iTime * 0.1))), fract(noiseUV.x));
    noise = mix(noise, hash12(floor(noiseUV + vec2(0.0, iTime * 0.1 + 1.0))), fract(noiseUV.y));
    noise = mix(noise, hash12(floor(noiseUV + vec2(1.0, iTime * 0.1 + 1.0))), fract(noiseUV.x));

    float dist = length((uv - center) * aspect);
    float wave = cos(dist * 50.0 - iTime * 10.0) * 0.02;

    float dropStrength = 0.08;
    int numDrops = 10;
    float totalDisplacement = 0.0;

    for (int i = 0; i < numDrops; ++i) {
        float seed = float(i) * 0.1234 + iTime * 0.1;
        vec2 dropPos = fract(hash22(vec2(seed, 0.0)) + iTime * 0.05) * 0.8 + 0.1;
        float dropLife = fract(hash12(vec2(seed, 1.0)) * 1.0 + iTime * 0.5);
        float dropRadius = mix(0.01, 0.2, smoothstep(0.0, 0.8, dropLife));
        dropRadius = mix(dropRadius, 0.0, smoothstep(0.8, 1.0, dropLife));

        float dropDist = length((uv - dropPos) * aspect);

        float dropEffect = max(0.0, dropRadius - dropDist) / max(0.001, dropRadius);
        dropEffect = pow(dropEffect, 2.0);
        dropEffect *= sin((dropDist / dropRadius * 15.0 - iTime * 5.0) * 0.5 + iTime * 0.2);
        totalDisplacement += dropEffect * dropStrength;
    }

    vec2 rippleUV = uv + totalDisplacement * 0.05 * aspect;

    vec3 waterColor = vec3(0.1, 0.3, 0.5) * (1.0 + totalDisplacement * 0.5);

    float reflectivity = smoothstep(-0.1, 0.1, totalDisplacement) * 0.7 + 0.1;
    vec3 reflectionColor = vec3(0.8, 0.9, 1.0);

    vec3 finalColor = mix(waterColor, reflectionColor, reflectivity);

    fragColor = vec4(finalColor, 1.0);
}

#define PI 3.14159265359

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

// Black hole parameters
const float BH_RADIUS = 0.15; // Schwarzschild radius (scaled)
const float ACCRETION_START = 0.2;
const float ACCRETION_END = 0.5;

// Raymarch parameters
const int MAX_STEPS = 90;
const float MIN_DIST = 0.001;
const float MAX_DIST = 100.0;
const float STEP_FACTOR = 0.8;

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 0.0, -1.5); // Ray origin
    vec3 rd = normalize(vec3(uv, 1.0)); // Ray direction

    // Simple camera wobble
    float wobbleStrength = 0.05;
    float wobbleSpeed = 1.0;
    ro.x += sin(iTime * wobbleSpeed) * wobbleStrength;
    ro.y += cos(iTime * wobbleSpeed * 0.7) * wobbleStrength;

    // Rotate view slightly
    float angle = iTime * 0.1;
    mat3 rotX = mat3(
        1.0, 0.0, 0.0,
        0.0, cos(angle), -sin(angle),
        0.0, sin(angle), cos(angle)
    );
    mat3 rotY = mat3(
        cos(angle*0.5), 0.0, sin(angle*0.5),
        0.0, 1.0, 0.0,
        -sin(angle*0.5), 0.0, cos(angle*0.5)
    );
    rd = rotY * rotX * rd;

    vec3 color = vec3(0.0);
    float t = 0.0;

    // Raymarch loop for light bending
    for (int i = 0; i < MAX_STEPS; ++i) {
        float distToBH = length(ro);

        if (distToBH < BH_RADIUS) { // Event horizon hit
            color = vec3(0.0); // Pure black
            break;
        }

        // Gravitational lensing / light bending towards the black hole
        vec3 bhToRay = normalize(ro);
        float bendFactor = pow(clamp(BH_RADIUS / distToBH, 0.0, 1.0), 2.0) * 0.5;
        rd = normalize(rd - bhToRay * bendFactor);

        t += STEP_FACTOR * distToBH; // Adaptive step size
        ro += rd * t;

        // Accretion disk check (simplified)
        if (distToBH > ACCRETION_START && distToBH < ACCRETION_END) {
            float diskHeight = abs(ro.z);
            float diskThickness = 0.02 * (1.0 - (abs(distToBH - (ACCRETION_START + ACCRETION_END) * 0.5) / ((ACCRETION_END - ACCRETION_START) * 0.5)));

            if (diskHeight < diskThickness) {
                // Disk color with turbulence and heat
                float diskIntensity = 1.0 - smoothstep(ACCRETION_START, ACCRETION_END, distToBH);
                diskIntensity *= 0.5 + 0.5 * noise(ro.xy * 10.0 + iTime * 2.0);

                vec3 diskColor = mix(vec3(0.8, 0.4, 0.1), vec3(1.0, 0.8, 0.5), smoothstep(BH_RADIUS, ACCRETION_START, distToBH));
                color = diskColor * diskIntensity * (1.0 - smoothstep(diskThickness * 0.8, diskThickness, diskHeight));
                color = pow(color, vec3(1.5)); // Brighter in the center
                break;
            }
        }

        // Star field (background)
        float bg_star_density = 0.005;
        float star_brightness = 1.0;
        float start_fade_dist = 50.0;
        if (distToBH > start_fade_dist) {
            vec2 star_uv = (ro.xy + ro.z) * 0.001;
            float star_noise = random(floor(star_uv * 5000.0));
            if (star_noise < bg_star_density) {
                color += vec3(star_brightness) * (1.0 - clamp(t / MAX_DIST, 0.0, 1.0));
            }
        }

        if (t > MAX_DIST) {
            // Far field background stars
            vec2 star_uv = normalize(rd).xy;
            float star_noise = random(floor(star_uv * 1000.0));
            if (star_noise < 0.001) {
                color += vec3(1.0); // Simple white stars
            }
            break;
        }
    }

    fragColor = vec4(color, 1.0) * (sin(iTime*0.5) * 0.1 + 0.9); // Subtle pulsation
    fragColor = pow(fragColor, vec4(0.4545)); // Gamma correction
}

#define PI 3.14159265359

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f*f*(3.0-2.0*f);

    return mix(mix(a, b, u.x),
               mix(c, d, u.x), u.y);
}

float fbm(vec2 st) {
    float value = 0.0;
    float amplitude = 0.5;
    for (int i = 0; i < 3; i++) {
        value += amplitude * noise(st);
        st *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec3 finalColor = vec3(0.0);

    // Helix parameters
    float radius = 0.2;
    float pitch = 1.5;
    float speed = iTime * 0.15;

    // Camera/tilt-shift focus point
    vec2 focus = vec2(0.5, 0.5);
    float blurAmount = abs(uv.y - focus.y) * 4.0;

    for (int i = 0; i < 20; i++) {
        float t = float(i) / 20.0 * 2.0 * PI * 4.0 + speed;

        float x = radius * sin(t);
        float y = radius * cos(t);
        float z = mod(t / (2.0 * PI * 4.0) + uv.x - 0.5 + iTime * 0.05, 1.0) - 0.5;

        // Project 3D point to 2D screen space
        vec2 p = vec2(x * 1.5 + 0.5, y * 1.5 + 0.5);

        float dist = distance(uv, p);
        float brightness = max(0.0, 0.015 - dist);

        // DNA base color variation
        vec3 color1 = vec3(0.2, 0.8, 0.2); // Green
        vec3 color2 = vec3(0.8, 0.2, 0.2); // Red
        vec3 color3 = vec3(0.2, 0.2, 0.8); // Blue
        vec3 color4 = vec3(0.8, 0.8, 0.2); // Yellow

        vec3 strandColor;
        float choice = fract(t * 0.1); // Deterministic color choice based on position
        if (choice < 0.25) strandColor = color1;
        else if (choice < 0.5) strandColor = color2;
        else if (choice < 0.75) strandColor = color3;
        else strandColor = color4;

        finalColor += strandColor * brightness * (1.0 - blurAmount);

        // Add connecting rungs
        if (i % 2 == 0 && i < 19) {
            float t_next = float(i+1) / 20.0 * 2.0 * PI * 4.0 + speed;
            float x_next = radius * sin(t_next);
            float y_next = radius * cos(t_next);

            vec2 p_next = vec2(x_next * 1.5 + 0.5, y_next * 1.5 + 0.5);

            // Simple line rendering for rungs
            float rung_dist = distance(uv, mix(p, p_next, 0.5));
            float rung_thickness = 0.005;
            float rung_blend = smoothstep(rung_thickness + 0.005, rung_thickness - 0.005, rung_dist*1.2);
            finalColor += mix(vec3(0.0), vec3(0.8), rung_blend * 0.5) * (1.0 - blurAmount);
        }
    }

    // Tilt-shift blur application (simple approximation)
    float vignette = 1.0 - distance(uv, vec2(0.5)) * 0.9;
    vignette = pow(vignette, 0.8);

    // Grain for microscopic feel
    float grain = fbm(uv * 15.0 + iTime * 0.1) * 0.1;
    finalColor += grain * 0.1 * (1.0 - blurAmount);

    finalColor *= vignette;

    // Apply a subtle color tint for medical feel
    finalColor = mix(finalColor, vec3(0.8, 0.9, 1.0) * finalColor, 0.15);

    fragColor = vec4(finalColor, 1.0);
}

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec2 rotate2D(vec2 v, float angle) {
    return vec2(
        v.x * cos(angle) - v.y * sin(angle),
        v.x * sin(angle) + v.y * cos(angle)
    );
}

float sdTriangle(vec2 p, float size) {
    p = abs(p);
    p.x -= p.y * 0.5;
    return max(p.x * 0.866025 + p.y * 0.5,
               p.y - size * 0.5);
}

float sdHexagon(vec2 p, float size) {
    vec2 q = abs(p);
    return max(q.x + q.y * 0.57735,
               q.y * 1.1547) - size;
}

float sdCircle(vec2 p, float r) {
    return length(p) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 color = vec3(0.0);

    float time = iTime * 0.5;

    vec2 grid_uv = uv * 5.0;
    vec2 cell_id = floor(grid_uv);
    vec2 local_uv = fract(grid_uv) - 0.5;

    float cell_rand = random(cell_id + time * 0.1);

    if (mod(cell_id.x + cell_id.y, 2.0) < 0.5) {
        local_uv = rotate2D(local_uv, iTime * 0.1 + cell_rand * 2.0);
        float tri_dist = sdTriangle(local_uv * 1.5, 0.5);
        color = mix(vec3(0.1, 0.4, 0.7), vec3(0.7, 0.2, 0.1), smoothstep(0.0, 0.05, tri_dist));
        color = mix(color, vec3(0.9, 0.8, 0.3), smoothstep(0.0, 0.1, tri_dist + sin(iTime * 1.5 + cell_rand * 10.0) * 0.05));
    } else {
        local_uv = rotate2D(local_uv, -iTime * 0.05 + cell_rand * 3.0);
        float hex_dist = sdHexagon(local_uv, 0.3 + sin(iTime * 2.0 + cell_rand * 5.0) * 0.1);
        color = mix(vec3(0.8, 0.1, 0.5), vec3(0.2, 0.6, 0.1), smoothstep(0.0, 0.03, hex_dist));
        color = mix(color, vec3(0.9, 0.5, 0.1), smoothstep(0.0, 0.08, hex_dist + cos(iTime * 1.0 + cell_rand * 8.0) * 0.04));
    }

    float border_dist_x = abs(local_uv.x) - 0.45;
    float border_dist_y = abs(local_uv.y) - 0.45;
    float border = max(border_dist_x, border_dist_y);
    color = mix(color, vec3(0.05, 0.05, 0.05), smoothstep(-0.02, 0.02, border));

    fragColor = vec4(color, 1.0);
}

#define PI 3.14159265359

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 st) {
    float value = 0.0;
    float amplitude = 0.5;
    float frequency = 0.0;
    for (int i = 0; i < 5; ++i) {
        value += amplitude * noise(st);
        st *= 2.0;
        amplitude *= 0.5;
    }
    return value;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 aspectCorrectedUv = uv * vec2(iResolution.x / iResolution.y, 1.0);

    float timeFactor = iTime * 0.1;

    vec2 offset = vec2(timeFactor, timeFactor * 0.5);

    float n = fbm(aspectCorrectedUv * 5.0 + offset);

    float height = pow(n, 1.5) * 0.6 + fbm(aspectCorrectedUv * 12.0 + offset * 2.0) * 0.2;
    height = mix(height, pow(height, 2.0), smoothstep(0.0, 0.7, n));

    vec3 lightDir = normalize(vec3(0.5, 0.7, -0.5));

    float dx = fbm((aspectCorrectedUv + vec2(0.01, 0.0)) * 5.0 + offset);
    float dy = fbm((aspectCorrectedUv + vec2(0.0, 0.01)) * 5.0 + offset);

    vec3 normal = normalize(vec3(dx - n, dy - n, 0.05)); // Simple normal for lighting
    float diffuse = clamp(dot(normal, lightDir), 0.0, 1.0);

    vec3 mountainColor = mix(vec3(0.1, 0.2, 0.3), vec3(0.4, 0.5, 0.55), height);
    vec3 snowColor = vec3(0.9, 0.95, 1.0);
    vec3 waterColor = vec3(0.0, 0.2, 0.4);

    vec3 finalColor;
    if (height < 0.15) {
        finalColor = mix(waterColor, vec3(0.1, 0.3, 0.5), smoothstep(0.0, 0.15, height));
        finalColor *= (0.8 + 0.2 * sin(aspectCorrectedUv.x * 20.0 + iTime * 2.0)); // Simple wave effect
    } else if (height > 0.7) {
        finalColor = mix(mountainColor, snowColor, smoothstep(0.7, 0.85, height));
    } else {
        finalColor = mountainColor;
    }

    finalColor *= (0.8 + diffuse * 0.7);

    fragColor = vec4(finalColor, 1.0);
}

precision highp float;

float Hash21(vec2 p) {
    p = fract(p * vec2(123.34, 345.54));
    p += dot(p, p + 78.23);
    return fract(p.x * p.y);
}

float Noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = Hash21(i);
    float b = Hash21(i + vec2(1.0, 0.0));
    float c = Hash21(i + vec2(0.0, 1.0));
    float d = Hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float Fbm(vec2 p) {
    float f = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        f += amp * Noise(p);
        p *= 2.0;
        amp *= 0.5;
    }
    return f;
}

vec3 SkyColor(vec3 rayDir) {
    float sunIntensity = max(0.0, dot(rayDir, normalize(vec3(0.5, 0.5, -1.0))));
    vec3 sunColor = vec3(1.0, 0.9, 0.7) * pow(sunIntensity, 256.0);
    vec3 atmosphere = mix(vec3(0.5, 0.7, 1.0), vec3(0.1, 0.3, 0.6), max(0.0, rayDir.y));
    return atmosphere + sunColor;
}

float RandScalar(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

vec3 RandVec3(vec2 co) {
    return vec3(RandScalar(co)), RandScalar(co + vec2(1.0, 0.0)), RandScalar(co + vec2(0.0, 1.0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 camPos = vec3(0.0, 1.0, -3.0);
    vec3 camTarget = vec3(0.0, 0.8, 0.0);
    vec3 camUp = vec3(0.0, 1.0, 0.0);

    vec3 camForward = normalize(camTarget - camPos);
    vec3 camRight = normalize(cross(camForward, camUp));
    vec3 camUpActual = normalize(cross(camRight, camForward));

    float FOV = 1.0;
    vec3 rayDir = normalize(camRight * uv.x * FOV + camUpActual * uv.y * FOV + camForward);

    vec3 finalColor = SkyColor(rayDir);

    if (rayDir.y < 0.0) {
        float yPos = -rayDir.y * 10.0; // Distance based on vertical angle
        float noiseVal = Fbm(rayDir.xz * 1.5 + vec2(iTime * 0.1, iTime * 0.05));
        float mountainHeight = pow(noiseVal, 2.5) * 2.0;

        float horizonMix = smoothstep(0.0, 0.05, -rayDir.y + 0.1);
        horizonMix = clamp(horizonMix, 0.0, 1.0);

        vec3 groundColor = mix(vec3(0.2, 0.4, 0.2), vec3(0.4, 0.5, 0.4), mountainHeight * 0.5);

        finalColor = mix(finalColor, groundColor, horizonMix);

        // Additional FBM for foreground hills/texture
        float nearNoise = Fbm(uv * 5.0 + iTime * 0.1);
        finalColor = mix(finalColor, vec3(0.3, 0.35, 0.25), nearNoise * 0.1 * horizonMix);
    }

    // Simple fog
    float fogDensity = 0.5;
    float fogAmount = exp(-rayDir.y * fogDensity ); 

    vec3 fogColor = vec3(0.5, 0.6, 0.7);
    finalColor = mix(finalColor, fogColor, clamp(1.0 - fogAmount, 0.0, 1.0)); 

    fragColor = vec4(finalColor, 1.0);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 ip = floor(p);
    vec2 u = fract(p);
    u = u * u * (3.0 - 2.0 * u);
    float res = mix(
        mix(hash(ip), hash(ip + vec2(1.0, 0.0)), u.x),
        mix(hash(ip + vec2(0.0, 1.0)), hash(ip + vec2(1.0, 1.0)), u.x),
        u.y
    );
    return res;
}

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;

    float scale = 3.0;
    vec2 p = uv * scale;
    vec2 ip = floor(p);
    vec2 fp = fract(p);

    float minDist = 8.0;
    vec2 closestCell = vec2(0.0);

    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 offset = vec2(float(x), float(y));
            vec2 cell = ip + offset;
            vec2 cellPos = cell + vec2(noise(cell * 10.0 + iTime * 0.1), noise(cell * 10.0 + iTime * 0.1 + 0.5)) - 0.5;
            vec2 diff = cellPos - fp;
            float dist = dot(diff, diff);

            if (dist < minDist) {
                minDist = dist;
                closestCell = cell;
            }
        }
    }

    float n = noise(closestCell * 5.0 + iTime * 0.05);
    vec3 color = palette(n + iTime * 0.1);
    color *= smoothstep(0.0, 0.1, 1.0 - sqrt(minDist));
    color *= smoothstep(0.0, 0.5, abs(sin(iTime * 0.5 + dot(uv, uv) * 5.0)));

    fragColor = vec4(color, 1.0);
}
